 5	export async function fetchWithRetry(
 6	  url: string,
 7	  attempts = 3,
 8	  baseDelayMs = 200,
 9	): Promise<Response> {
10	  let lastError: unknown;
11	  for (let attempt = 0; attempt < attempts; attempt++) {
12	    try {
13	      const response = await fetch(url);
14	      if (response.status < 500) {
15	        return response;
16	      }
17	      lastError = new Error(`server error ${response.status}`);
18	    } catch (error) {
19	      lastError = error;
20	    }
21	    await new Promise((resolve) => setTimeout(resolve, baseDelayMs * 2 ** attempt));
22	  }
23	  throw lastError;
24	}
